head.script:
scwin.getQueryParam = function (name) {
    try {
        const params = new URLSearchParams(window.location.search);
        const value = params.get(name);
        return value;
    } catch (e) {
        return null;
    }
};

// 역할별 탭 접근 권한 정의 
scwin.rolePermissions = {
    'ADMIN': {
        tabs: ['user', 'module', 'login', 'meeting', 'attenance', 'moduleManagement'],
        description: '모든 기능에 접근 가능'
    },
    'MANAGER': {
        tabs: ['user', 'module', 'login', 'meeting', 'attenance', 'moduleManagement'],
        description: '모든 기능에 접근 가능'
    },
    'USER': {
        tabs: ['meeting', 'attenance'],
        description: '미팅 관련 기능만 접근 가능'
    }
};

scwin.createPopupLayer = function () {
    if (document.getElementById('customAlertPopup')) return;

    var popupHtml = `
        <div id="customAlertPopup" style="position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 9999; display: none; align-items: center; justify-content: center; font-family: 'Pretendard', sans-serif;">
            <div style="background: white; padding: 24px; border-radius: 8px; box-shadow: 0 5px 15px rgba(0,0,0,0.3); min-width: 320px; max-width: 450px; text-align: center; box-sizing: border-box;">
                <div id="popupMessage" style="margin-bottom: 24px; font-size: 16px; line-height: 1.6; color: #333; white-space: pre-wrap; word-break: break-word;"></div>
                <div>
                    <button id="popupConfirm" style="background: #007bff; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">확인</button>
                    <button id="popupCancel" style="background: #6c757d; color: white; border: none; padding: 10px 20px; margin: 0 5px; border-radius: 5px; cursor: pointer; font-size: 14px; font-weight: 500;">취소</button>
                </div>
            </div>
        </div>
    `;
    document.body.insertAdjacentHTML('beforeend', popupHtml);
};


// 팝업 표시 함수
scwin.showPopup = function (message, isConfirm, callback) {
    var popup = document.getElementById('customAlertPopup');
    if (!popup) {
        // 혹시 팝업이 없는 경우를 대비해 생성
        scwin.createPopupLayer();
        popup = document.getElementById('customAlertPopup');
    }

    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    messageEl.innerHTML = message.replace(/\\n/g, '<br>');

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(true);
        };
        cancelBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(false);
        };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback();
        };
    }

    popup.style.display = 'flex';
};

// 테넌트 정보를 저장할 전역 변수
scwin.tenantName = null;
scwin.tenantDisplayName = null;

scwin.parseJwt = function (token) {
    try {
        const base64Url = token.split('.')[1];
        const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
        const jsonPayload = decodeURIComponent(atob(base64).split('').map(function (c) {
            return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
        }).join(''));
        return JSON.parse(jsonPayload);
    } catch (e) {
        return null;
    }
};


scwin.getQueryParam = function (name) {
    try {
        // 현재 페이지 URL에서 파라미터 추출
        const params = new URLSearchParams(window.location.search);
        const value = params.get(name);
        return value;
    } catch (e) {
        return null;
    }
};

scwin.preserveTenantInfo = function () {
    try {

        const sources = [
            scwin.tenantDisplayName,
            sessionStorage.getItem('currentTenantName'),
            scwin.getQueryParam('tenant'),
            scwin.tenantName 
        ];


        const finalTenant = sources.find(t => t && t.trim() && t !== 'null' && t !== 'undefined');

        if (finalTenant) {
            localStorage.setItem('logoutTenantId', finalTenant);
            sessionStorage.setItem('logoutTenantBackup', finalTenant);
            window.logoutTenantInfo = finalTenant;
            return finalTenant;
        } else {
            return null;
        }
    } catch (e) {
        return null;
    }
};
// 테넌트 정보 가져오기 함수
scwin.fetchTenantInfo = function (tenantId) {

    // sessionStorage에서 테넌트 이름 먼저 확인
    const savedTenantName = sessionStorage.getItem('currentTenantName');

    if (savedTenantName) {
        scwin.updateHeaderTitle(savedTenantName + " Dashboard");
        scwin.tenantDisplayName = savedTenantName;
        return;
    }

    if (!tenantId) {
        scwin.updateHeaderTitle("Dashboard");
        return;
    }

    $p.ajax({
        url: `/api/tenants/${tenantId}`,
        method: "GET",
        headers: {
            "Authorization": sessionStorage.getItem('accessToken'),
            "Content-Type": "application/json"
        },
        success: function (response) {

            if (response && response.name) {
                scwin.tenantDisplayName = response.name;
                scwin.updateHeaderTitle(response.name + " Dashboard");
                sessionStorage.setItem('currentTenantName', response.name);
            } else {
                scwin.tenantDisplayName = tenantId;
                scwin.updateHeaderTitle(tenantId + " Dashboard");
                sessionStorage.setItem('currentTenantName', tenantId);
            }
        },
        error: function (xhr, status, error) {

            if (xhr.status === 403 || xhr.status === 401) {
                scwin.showPopup("세션이 만료되었거나 접근 권한이 없습니다. 다시 로그인합니다.", false, scwin.performLogout);
            } else {
                scwin.updateHeaderTitle("Dashboard (Error)");
            }
        }
    });
};




scwin.updateHeaderTitle = function (title) {
    try {
        var headerTitleComp = $p.getComponentById("headerTitle");

        if (headerTitleComp) {
            headerTitleComp.setLabel(title);
        } else {
            console.error("headerTitle 컴포넌트를 찾을 수 없습니다.");
        }
    } catch (e) {
        console.error("헤더 타이틀 업데이트 중 오류 발생:", e);
    }
};

// 로그아웃 함수
scwin.logout = function () {

    const currentTenant = scwin.preserveTenantInfo();

    const tenantDisplayName = scwin.tenantDisplayName ||
        scwin.tenantName ||
        currentTenant ||
        sessionStorage.getItem('currentTenantName') ||
        "현재 테넌트";

    const message = `${tenantDisplayName}에서 로그아웃 하시겠습니까?`;

    scwin.showPopup(message, true, function (confirmed) {
        if (confirmed) {

            $p.ajax({
                url: "/InsWebApp/TNU0000Logout.pwkjson",
                method: "POST",
                headers: {
                    "Authorization": sessionStorage.getItem('accessToken'),
                    "Content-Type": "application/json"
                },
                success: function (response) {
                    scwin.performLogout();
                },
                error: function (xhr, status, error) {
                    scwin.performLogout();
                }
            });
        } else {
            console.log("사용자가 로그아웃 취소함");
        }
    });
};


scwin.getCurrentDomainInfo = function () {
    try {
        const currentUrl = window.location.href;

        const urlObj = new URL(currentUrl);

        const domainInfo = {
            protocol: urlObj.protocol,
            hostname: urlObj.hostname,
            port: urlObj.port,
            baseUrl: `${urlObj.protocol}//${urlObj.hostname}${urlObj.port ? ':' + urlObj.port : ''}`
        };

        return domainInfo;
    } catch (e) {
        return {
            protocol: 'https:',
            hostname: 'localhost',
            port: '19443',
            baseUrl: 'https://localhost:19443'
        };
    }
};

// 테넌트 로그인 URL 생성 함수
scwin.buildTenantLoginUrl = function (tenantId) {
    const domainInfo = scwin.getCurrentDomainInfo();

    let loginUrl;

    if (tenantId && tenantId.trim() && tenantId !== 'null' && tenantId !== 'undefined') {
        // 테넌트 정보가 있는 경우
        const cleanTenantId = tenantId.trim();
        loginUrl = `${domainInfo.baseUrl}/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_tenant_login_page.xml&tenant=${encodeURIComponent(cleanTenantId)}`;
    } else {
        // 테넌트 정보가 없는 경우 - 기본 로그인 페이지
        loginUrl = `${domainInfo.baseUrl}/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_tenant_login_page.xml`;
    }

    // 캐시 방지를 위한 타임스탬프 추가
    const timestamp = new Date().getTime();
    loginUrl += `&_t=${timestamp}`;

    return loginUrl;
};


// 테스트용 함수
scwin.testLogoutUrl = function () {

    const currentDomain = scwin.getCurrentDomainInfo();
    const tenantId = scwin.tenantName || scwin.getQueryParam('tenant') || 'TestTenant';
    const loginUrl = scwin.buildTenantLoginUrl(tenantId);

    return loginUrl;
};

scwin.performLogout = function () {

    try {
        const preservedTenant = scwin.preserveTenantInfo();

        let finalTenantId = preservedTenant;

        if (!finalTenantId) {
            finalTenantId = localStorage.getItem('logoutTenantId');
        }

        if (!finalTenantId) {
            finalTenantId = window.logoutTenantInfo;
        }

        try {
            sessionStorage.clear();
            localStorage.removeItem('refreshToken');
            if (finalTenantId) {
                localStorage.setItem('logoutTenantId', finalTenantId);
            }
        } catch (e) {
            console.error("세션 클리어 오류:", e);
        }

        const loginUrl = scwin.buildTenantLoginUrl(finalTenantId);


        const redirectMethods = [
            () => window.location.href = loginUrl,
            () => window.location.replace(loginUrl),
            () => window.top.location.href = loginUrl,
            () => window.parent.location.href = loginUrl,
            () => document.location.href = loginUrl
        ];

        let redirectSuccess = false;

        for (let i = 0; i < redirectMethods.length; i++) {
            try {
                redirectMethods[i]();
                redirectSuccess = true;
                break;
            } catch (e) {
                continue;
            }
        }

        if (!redirectSuccess) {

            const message = `로그아웃이 완료되었습니다.\n다음 링크를 클릭해서 로그인 페이지로 이동해주세요:\n\n${loginUrl}`;

            if (confirm(message)) {
                try {
                    navigator.clipboard.writeText(loginUrl);
                    alert("URL이 클립보드에 복사되었습니다.");
                } catch (e) {
                    console.error("클립보드 복사 실패:", e);
                }
            }
        }

    } catch (error) {

        try {
            sessionStorage.clear();
            localStorage.removeItem('refreshToken');
        } catch (e) {
            console.error("긴급 세션 클리어 오류:", e);
        }

        const domainInfo = scwin.getCurrentDomainInfo();
        const safeUrls = [
            `${domainInfo.baseUrl}/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_tenant_login_page.xml`,
            `${domainInfo.baseUrl}/InsWebApp/`,
            `${domainInfo.baseUrl}/`
        ];

        for (let url of safeUrls) {
            try {
                window.location.href = url;
                break;
            } catch (e) {
                continue;
            }
        }

        alert("로그아웃 중 오류가 발생했습니다. 브라우저를 새로고침한 후 다시 로그인해주세요.");
    }
};

scwin.initializeTabPermissions = function () {

    const accessToken = sessionStorage.getItem('accessToken');

    if (!accessToken) {
        scwin.currentUserRole = 'USER';
        scwin.allowedTabs = ['meeting', 'history'];
        scwin.applyTabPermissions();
        return true;
    }

    try {
        const tokenString = accessToken.startsWith('Bearer ') ? accessToken.substring(7) : accessToken;
        const tokenPayload = scwin.parseJwt(tokenString);

        if (!tokenPayload) {
            scwin.currentUserRole = 'USER';
            scwin.allowedTabs = ['meeting', 'history'];
            scwin.applyTabPermissions();
            return true;
        }

        let userRole = tokenPayload.role;
        if (userRole) {
            userRole = userRole.toString().trim().toUpperCase();
        }


        if (!userRole || !scwin.rolePermissions[userRole]) {
            scwin.currentUserRole = 'USER';
            scwin.allowedTabs = ['meeting', 'history'];
        } else {
            scwin.currentUserRole = userRole;
            scwin.allowedTabs = scwin.rolePermissions[userRole].tabs;
        }


        scwin.applyTabPermissions();

        return true;

    } catch (error) {
        scwin.currentUserRole = 'USER';
        scwin.allowedTabs = ['meeting', 'history'];
        scwin.applyTabPermissions();
        return true;
    }
};


scwin.fetchTenantInfo = function (tenantId) {

    const savedTenantName = sessionStorage.getItem('currentTenantName');

    if (savedTenantName) {
        scwin.updateHeaderTitle(savedTenantName + " Dashboard");
        scwin.tenantDisplayName = savedTenantName;
        return;
    }

    if (!tenantId) {
        scwin.updateHeaderTitle("Dashboard");
        return;
    }

    $p.ajax({
        url: `/api/tenants/${tenantId}`,
        method: "GET",
        headers: {
            "Authorization": sessionStorage.getItem('accessToken'),
            "Content-Type": "application/json"
        },
        success: function (response) {

            if (response && response.name) {
                scwin.tenantDisplayName = response.name;
                scwin.updateHeaderTitle(response.name + " Dashboard");
                sessionStorage.setItem('currentTenantName', response.name);
            } else {
                scwin.updateHeaderTitle("Dashboard");
            }
        },
        error: function (xhr, status, error) {
            scwin.updateHeaderTitle("Dashboard");
        }
    });
};

scwin.applyTabPermissions = function () {

    const allTabs = ['user', 'module', 'login', 'meeting', 'attenance', 'moduleManagement'];
    let visibleTabCount = 0;
    let firstVisibleTab = null;

    setTimeout(function () {

        allTabs.forEach(function (tabName) {
            let tabElement = null;
            const possibleIds = [
                'tab_' + tabName,
                'mf_tab_' + tabName,
                'tab-' + tabName,
                'mf_tab-' + tabName
            ];

            for (let id of possibleIds) {
                tabElement = document.getElementById(id);
                if (tabElement) {
                    break;
                }
            }

            if (tabElement) {
                const hasPermission = scwin.allowedTabs && scwin.allowedTabs.indexOf(tabName) > -1;

                if (hasPermission) {
                    tabElement.style.display = 'inline-block';
                    tabElement.style.visibility = 'visible';
                    tabElement.classList.remove('hidden-tab');

                    visibleTabCount++;
                    if (!firstVisibleTab) {
                        firstVisibleTab = tabName;
                    }

                } else {
                    tabElement.style.display = 'none';
                    tabElement.style.visibility = 'hidden';
                    tabElement.classList.add('hidden-tab');

                }
            } else {
                console.warn(`탭 요소를 찾을 수 없음: ${tabName} (시도한 ID들: ${possibleIds.join(', ')})`);
            }
        });

        const allElements = document.querySelectorAll('[id*="tab"]');
        allElements.forEach(el => {
            console.log(`- ID: ${el.id}, TagName: ${el.tagName}, Text: ${el.textContent?.trim()}`);
        });


        if (firstVisibleTab) {
            setTimeout(function () {
                scwin.switchTab(firstVisibleTab);
            }, 100);
        } else {
            console.warn("표시할 수 있는 탭이 없습니다. DOM 구조를 확인해주세요.");
        }
    }, 100);
};


scwin.switchTabWithPermission = function (tabName) {

    // 권한 체크
    if (!scwin.allowedTabs || scwin.allowedTabs.indexOf(tabName) === -1) {
        return;
    }

    // 기존 탭 전환 로직 실행
    scwin.switchTab(tabName);
};

// 권한별 메시지 표시
scwin.showRoleInfo = function () {
    if (scwin.currentUserRole && scwin.rolePermissions[scwin.currentUserRole]) {
        const roleInfo = scwin.rolePermissions[scwin.currentUserRole];
        const message = `현재 권한: ${scwin.currentUserRole}\n` +
            `설명: ${roleInfo.description}\n` +
            `사용 가능한 기능: ${roleInfo.tabs.join(', ')}`;

        scwin.showPopup(message);
    }
};


scwin.switchTabWithPermission = function (tabName) {

    // 권한 체크
    if (!scwin.allowedTabs || scwin.allowedTabs.indexOf(tabName) === -1) {
        return;
    }

    // 기존 탭 전환 로직 실행
    scwin.switchTab(tabName);
};

// 권한별 메시지 표시
scwin.showRoleInfo = function () {
    if (scwin.currentUserRole && scwin.rolePermissions[scwin.currentUserRole]) {
        const roleInfo = scwin.rolePermissions[scwin.currentUserRole];
        const message = `현재 권한: ${scwin.currentUserRole}\n` +
            `설명: ${roleInfo.description}\n` +
            `사용 가능한 기능: ${roleInfo.tabs.join(', ')}`;

        scwin.showPopup(message);
    }
};


scwin.onpageload = function () {
    scwin.createPopupLayer();

    const urlTenant = $p.getParameter("tenant");

    const accessToken = sessionStorage.getItem('accessToken');

    if (!accessToken) {
        scwin.showPopup("로그인 정보가 없습니다. 로그인 페이지로 이동합니다.", false, scwin.performLogout);
        return;
    }

    const tokenString = accessToken.startsWith('Bearer ') ? accessToken.substring(7) : accessToken;
    const tokenPayload = scwin.parseJwt(tokenString);
    const tokenTenant = tokenPayload ? tokenPayload.tenantId : null;

    if (!tokenTenant) {
        scwin.showPopup("사용자 정보가 올바르지 않습니다. 다시 로그인해주세요.", false, scwin.performLogout);
        return;
    }

    if (urlTenant && urlTenant !== tokenTenant) {

        scwin.showPopup("접근 권한이 없는 페이지입니다. 사용자의 대시보드로 이동합니다.", false, () => {
            const correctPath = window.location.pathname + "?w2xPath=/InsWebApp/main/tenant_dashboard/tenant_user_dashboard.xml&tenant=" + tokenTenant;
            window.location.replace(correctPath);
        });

        return;
    }

    scwin.tenantName = tokenTenant;

    if (!urlTenant) {
        const newUrl = window.location.pathname + window.location.search + "&tenant=" + tokenTenant;
        window.history.replaceState({ path: newUrl }, '', newUrl);
    }

    scwin.initializeTabPermissions();
    scwin.fetchTenantInfo(scwin.tenantName);

};


/**
 * 탭 전환 함수
 */
scwin.switchTab = function (tabName) {

    var allTabs = document.querySelectorAll('.tab-button');
    for (var i = 0; i < allTabs.length; i++) {
        allTabs[i].classList.remove('active');
    }

    var clickedTab = document.getElementById('tab_' + tabName);
    if (clickedTab) {
        clickedTab.classList.add('active');
    }

    scwin.showPanel(tabName);
};


scwin.showPanel = function (panelType) {

    var contentFrame = $p.getComponentById("contentFrame");

    if (!contentFrame) {
        alert("contentFrame을 찾을 수 없습니다!");
        return;
    }

    let pageUrl = "";
    const tenantParam = scwin.tenantName ? "?tenant=" + encodeURIComponent(scwin.tenantName) : "";

    if (panelType === 'user') {
        pageUrl = "user_management_dashboard.xml" + tenantParam;
    } else if (panelType === 'module') {
        pageUrl = "module_marketplace.xml" + tenantParam;
    } else if (panelType === 'login') {
        pageUrl = "login_custom.xml" + tenantParam;
    } else if (panelType === 'meeting') {
        pageUrl = "make_session_progress.xml" + tenantParam;
    } else if (panelType === 'attenance') {
        pageUrl = "attendance_module__dashboard.xml" + tenantParam;
    } else if (panelType === 'moduleManagement') {
        pageUrl = "module-management.xml" + tenantParam;
    } else {
        return;
    }

    contentFrame.setSrc(pageUrl);
};

scwin.validateUserAccess = function () {

    const accessToken = sessionStorage.getItem('accessToken');
    if (!accessToken) {
        return false;
    }

    try {
        const tokenString = accessToken.startsWith('Bearer ') ? accessToken.substring(7) : accessToken;
        const tokenPayload = scwin.parseJwt(tokenString);

        if (!tokenPayload) {
            return false;
        }


        const currentTime = Math.floor(Date.now() / 1000);
        if (tokenPayload.exp && tokenPayload.exp < currentTime) {
            return false;
        }

        return true;

    } catch (error) {
        return false;
    }
};

scwin.updateHeaderWithRoleInfo = function () {

    if (!scwin.currentUserRole) {
        return;
    }

    try {
        const headerElement = document.querySelector('.header h1');
        if (headerElement) {
            const existingBadge = headerElement.querySelector('.role-badge');
            if (existingBadge) {
                existingBadge.remove();
            }

            const roleBadge = document.createElement('span');
            roleBadge.className = `role-badge ${scwin.currentUserRole.toLowerCase()}`;
            roleBadge.textContent = scwin.currentUserRole;
            roleBadge.style.marginLeft = '10px';
            roleBadge.style.fontSize = '12px';
            roleBadge.style.padding = '4px 8px';
            roleBadge.style.borderRadius = '4px';

            headerElement.appendChild(roleBadge);

        }
    } catch (error) {
        console.error("헤더 업데이트 중 오류:", error);
    }
};

scwin.btn_kakao_onclick = function (e) {
    const host = window.location.hostname; 
    const tenant = host.split('.')[0];


    if (!tenant) {
        scwin.showPopup("테넌트 정보를 찾을 수 없습니다. 페이지를 새로고침해주세요.");
        return;
    }

    var service = "TNU0000KC";

    var url = "/InsWebApp/TNU0000KL.pwkjson?service="
        + service
        + "&tenant=" + encodeURIComponent(tenant);


    var subObj = $p.getSubmission("kakao_login");

    subObj.action = url;
    $p.executeSubmission("kakao_login");
};

scwin.getCurrentDomainInfo = function () {
    try {
        const currentUrl = window.location.href;
        const urlObj = new URL(currentUrl);

        const domainInfo = {
            protocol: urlObj.protocol, 
            hostname: urlObj.hostname, 
            port: urlObj.port,        
            baseUrl: `${urlObj.protocol}//${urlObj.hostname}${urlObj.port ? ':' + urlObj.port : ''}`
        };

        return domainInfo;
    } catch (e) {
        return {
            protocol: 'https:',
            hostname: 'localhost',
            port: '19443',
            baseUrl: 'https://localhost:19443'
        };
    }
};

scwin.buildTenantLoginUrl = function (tenantId) {
    const domainInfo = scwin.getCurrentDomainInfo();

    let loginUrl;

    if (tenantId && tenantId.trim() && tenantId !== 'null' && tenantId !== 'undefined') {
        loginUrl = `${domainInfo.baseUrl}/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_tenant_login_page.xml&tenant=${encodeURIComponent(tenantId.trim())}`;
    } else {
        loginUrl = `${domainInfo.baseUrl}/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_tenant_login_page.xml`;
    }

    const timestamp = new Date().getTime();
    loginUrl += `&_t=${timestamp}`;

    return loginUrl;
};

scwin.testLogoutProcess = function () {

    const domainInfo = scwin.getCurrentDomainInfo();

    const preserved = scwin.preserveTenantInfo();

    const loginUrl = scwin.buildTenantLoginUrl(preserved);

    return {
        tenant: preserved,
        domain: domainInfo,
        loginUrl: loginUrl
    };
};
